    weights={f"Q{i}":rng.choice([1,1,2,10**18,10**18+1]) for i in range(q)}
    return tuple(nodes),tuple(tasks),weights

def shares(nodes, iv, tick, w):
    tc=sum(n.capacity.cpu for n in nodes); tm=sum(n.capacity.memory for n in nodes)
    used={}
    for tid,q,c,m,s,e,node in iv:
        if s<=tick<e:
            a,b=used.get(q,(0,0)); used[q]=(a+c,b+m)
    return {q: max(Fraction(uc,tc) if tc else Fraction(0), Fraction(um,tm) if tm else Fraction(0))/w.get(q,1) for q,(uc,um) in used.items()}

def free(nodes,iv,tick):
    f={n.id:[n.capacity.cpu,n.capacity.memory] for n in nodes}
    for tid,q,c,m,s,e,node in iv:
        if s<=tick<e:
            f[node][0]-=c; f[node][1]-=m
    return f

def any_fit(nodes,t,fmap):
    return any(t.request.cpu<=fmap[n.id][0] and t.request.memory<=fmap[n.id][1] for n in nodes)

viol=0; runs=0
for seed in range(300):
    nodes,tasks,weights=gen(seed)
    for preempt in (False,True):
      for bf_on in (False,True):
        r=S.simulate(nodes,tasks,allow_preemption=preempt,backfill=bf_on,queue_weights=weights)
        runs+=1
        iv=[]; decided=set(); tmap={t.id:t for t in tasks}
        for d in r.decisions:
            if "at" not in d: continue
            tick=d["at"]; cur=tmap[d["task"]]
            fmap=free(nodes,iv,tick)
            sh=shares(nodes,iv,tick,weights)
            pending=[x for x in tasks if x.arrival<=tick and x.id not in decided]
            order=sorted(pending,key=lambda x:(-x.priority,sh.get(x.queue,Fraction(0)),x.arrival,x.queue,x.id))
            head=order[0]
            if d["reason"]=="backfill":
                if cur.id==head.id: viol+=1; print("backfill was head",seed)
                if any_fit(nodes,head,fmap): viol+=1; print("head fit but backfill jumped",seed)
                running=[z for z in iv if z[4]<=tick<z[5]]
                horizon=min(z[5] for z in running)
                for cand in order[1:]:
                    if cand.id==cur.id: break
                    if tick+cand.duration<=horizon and any_fit(nodes,cand,fmap):
                        viol+=1; print("earlier qualifier existed",seed,cand.id,"before",cur.id); break
            elif d["reason"].startswith("preempting "):
                if head.id!=cur.id: viol+=1; print("preempter not head",seed)
            elif "node" in d:
                if head.id!=cur.id: viol+=1; print("placed not exact head",seed,cur.id,head.id)
            if "node" in d:
                end=next(p for p in r.placements if p.task_id==cur.id).end
                iv.append((cur.id,cur.queue,cur.request.cpu,cur.request.memory,tick,end,d["node"]))
                decided.add(cur.id)
print(f"full-oracle big-int: {runs} runs, violations={viol}")
